"""Publish completed K/ramp results only after actual replay and still review."""
from __future__ import annotations
import argparse
import html
import json
from pathlib import Path

import analyze_ppo_k_leg_ramp as analysis


def run(root):
    root=Path(root);target=root/'completed_report.html';assert not target.exists()
    summary=analysis.read(root/'analysis/analysis.json')
    verified=analysis.read(root/'artifact_verification_v1.json')
    review=analysis.read(root/'still_review_v1.json')
    assert summary['analyzer_sha256']==analysis.sha(analysis.__file__)
    assert verified['frames_decoded']==350 and verified['fixed_relative_camera_verified']
    assert review['inspected_frame_indices']==[112,150,200,348]
    assert not review['full_manual_video_playback_claimed']
    for n,h in review['frame_sha256'].items():assert analysis.sha(root/'render'/n)==h
    rows=summary['rows'];assert [r['id'] for r in rows]==list(analysis.ORDER)
    table=[]
    for r in rows:
        core=r['metrics']['windows']['core'];sup=r['metrics']['any_wheel_ground_support']['full_contact']
        screen=r['nominal_screen']
        values=[r['title'],f"{core['tracking']['xy_rmse_m']*100:.2f}",f"{core['tracking']['speed_retention']*100:.2f}",
            f"{core['tracking']['beta_rmse_deg']:.2f}" if core['tracking']['beta_rmse_deg'] is not None else 'unavailable',
            f"{sup['any_wheel_support_sample_fraction']*100:.2f}",f"{sup['longest_no_support_observed_s']*1000:.1f}",
            f"{screen['core_HF_ratio_to_original_same_engine_PPO']:.3f}",f"{core['maximum_tilt_deg']:.2f}",
            ', '.join(screen['failed_checks']) or 'none']
        table.append('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in values)+'</tr>')
    passing=all(r['nominal_screen']['numeric_nominal_episode_pass'] for r in rows if r['variant']=='ramp')
    outcome=('Both new nominal episodes meet the retained numerical gates; complete task qualification still requires the separate qualitative completion audit.'
             if passing else 'The ramp-trained policy does not pass the original complete nominal task in both engines. Better individual metrics or completed learning do not establish continuous stable-contact turning.')
    notes=''.join('<p><strong>'+html.escape(r['title'])+'.</strong> '+html.escape(review['case_notes'][r['id']])+'</p>' for r in rows)
    text='''<!doctype html><html lang="en"><meta charset="utf-8"><title>K PPO trained for smooth leg commands: results</title><style>body{font:16px/1.6 system-ui;max-width:1500px;margin:30px auto;padding:20px}table{border-collapse:collapse;font-size:14px}td,th{border:1px solid #ccd4df;padding:9px;text-align:right}video,img{max-width:100%}.note{background:#fff3d6;padding:15px}code{overflow-wrap:anywhere}</style><h1>K PPO: training with physical leg-target ramps</h1><p class="note">OUTCOME</p><video controls playsinline preload="metadata" poster="render/comparison.png" src="render/fullbody_comparison.mp4"></video><p>Four actual6.98s episodes: original K and ramp-trained K, each in native PhysX and native CPU MuJoCo at mu0.7. Each policy has one actor across engines. Rendering replays original native poses with opaque meshes, body/wheel/velocity headings, one common fixed relative camera distance and fixed world angles, translation-only following and shared world-XY scale. No pose smoothing, root correction, resimulation or inferred contact is used.</p><table><tr><th>Cell</th><th>Core XY RMSE(cm)</th><th>Core speed(%)</th><th>Core beta RMSE(deg)</th><th>Any-wheel support(%)</th><th>Longest gap(ms)</th><th>HF/original</th><th>Core max tilt(deg)</th><th>Failed original gates</th></tr>TABLE</table><p>Core1.44–4.00s, whole-reference0–6.96s, support0.02–6.96s. Retained gates: core/whole XY RMSE≤0.15m and peak≤0.30m; core speed ratio0.95–1.10; intended nonzero reference-beta RMSE≤10deg; core angularXY10–100Hz RMS≤0.7 of original same-engine400Hz PPO; max wheel normal force&gt;5N every native2.5ms sample, support fraction100%, longest gap0. Single-wheel support and alternating support are allowed. No absolute height or geometric-flight gate is introduced. Body integrity and within-turn speed profile matter; support after falling and reduced HF after stopping do not establish success. N=1 is not robustness qualification.</p>REVIEW<img src="analysis/comparison.png" alt="Actual native XY, COM speed, normal force and body tilt"><p>This is a PhysX-trained, closed-loop transfer comparison. Native engine differences change later observations and policy actions; it does not isolate solver-only error or establish a general controller ranking.</p><h2>One execution intervention; all15 rewards retained</h2><p>The new actor is trained from scratch for512×24×1000=12288000 transitions, with the same seed42 initial network, K contact formula and external+0.4, remaining14 reward terms, beta+2, action-rate−0.5, PD500/10, original DC motor limits, observations, reference, rigid cylinders and native friction. Startup frictionDR[0.3,1.2], encoder bias, COM perturbations and pushes retain their original recipe. Validation has fixed mu0.7, no DR and no observation noise.</p><p>At50Hz the actor supplies six desired leg position actions and two wheel efforts. The six processed leg targets now move over eight actual400Hz physical applications, ending exactly at the desired target. Wheel efforts retain their hold. At each world's reset, the first application starts from measured native joint positions instead of carrying an old episode command. The policy observes the original raw previous action; no actor or observation filter is added. This is training for changed command execution, not evidence for a new reward formula alone.</p><p>The earlier frozen-policy ramp worsened support89.52% to86.60%. It was not presented as a fix. This new matched-budget experiment tests adaptation during learning. PhysX uses the same GPU runtime as training; CPU MuJoCo applies the same fractions and endpoints before its original DC motor calculation. All2792 actual desired/applied targets and held wheel efforts are recorded. Independent reconstruction checks the raw action mapping, reset start, fractions, endpoints and native motor torque envelope; full differences and declared0.005Nm/2e-5 torque-check tolerance appear in the JSON.</p><h2>Evaluation integration repair</h2><p>The first PhysX evaluation was rejected before any physical rollout because the training-only contact-reward collector checked the legacy evaluator's different beta-module source. Its process returned0 during headless cleanup, but the continuation rejected the missing completion artifacts. Training and the completed actor were retained. The repaired evaluation uses the same target-ramp runtime with a read-only native-counter adapter, preserving the original recorder, reward lifecycle and physics steps. The original failed source/status/log files remain in the completed collection; the two accepted episodes live in a separate nominal directory. No validation outcome or reward weight was used to select a replacement actor.</p><h2>Verification and reproduction</h2><p>The original18 CPU tests and native32-environment smoke passed before formal learning; the repaired evaluation interface passes20 CPU checks, including use of the unchanged training ramp with the original native evaluation clock. The CPU-only smoke execution additionally verified all2792 physical motor computations, but is excluded from this formal task comparison. Formal normalized-actor export, exact budget, initial-network identity and live ramp/contact audits were checked on the execution host. The completed evidence collection rehashed final actor/checkpoint files there and excluded their bytes, model assets, credentials and native libraries.</p><p>All350 frames decoded, native metrics were independently recomputed, common fixed cameras verified and stills2.24/3.00/4.00/6.96s inspected. Full manual video playback is not claimed. All owned training and nominal evaluation jobs are terminal. No friction sweep or validation tuning was performed. <a href="report.html">Dated launch/smoke evidence</a> remains unchanged.</p><p><a href="analysis/analysis.json">Native metrics and independent motor audit</a> · <a href="completed_evidence_v1.manifest.json">Completed execution-file hashes</a> · <a href="completed_evidence_v1/formal_v1_strict_verification.json">Formal training/export proof</a> · <a href="completed_evidence_v1/NOMINAL_DIR/status.json">Both native episodes</a> · <a href="artifact_verification_v1.json">Decode/camera/metric checks</a> · <a href="still_review_v1.json">Actual still review</a>.</p><p><a href="../../config/ppo_k_leg_ramp_400hz_v1.json">Frozen protocol and acceptance</a> · <a href="../../scripts/train_ppo_k_leg_ramp.py">Trainer</a> · <a href="../../scripts/ppo_batched_leg_ramp.py">GPU runtime</a> · <a href="../../scripts/eval_ppo_k_leg_ramp.py">Same-execution native evaluator</a> · <a href="../../scripts/analyze_ppo_k_leg_ramp.py">Analyzer</a> · <a href="../../scripts/render_ppo_k_leg_ramp.py">Renderer</a>. The exact launch records retain existing asset/dependency arguments. Offline analysis and replay require the locked reference and original local visual assets; they load no actor or weights.</p></html>'''
    for key,value in [('OUTCOME',html.escape(outcome)),('TABLE','\n'.join(table)),('REVIEW',notes)]:text=text.replace(key,value)
    text=text.replace('NOMINAL_DIR',analysis.collection.layout(root/'completed_evidence_v1')['nominal_directory'])
    target.write_text(text);print(json.dumps(dict(report=str(target),new_numeric_both_engines_pass=passing,task_success_claimed=False)))


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__,allow_abbrev=False);p.add_argument('--result',type=Path,required=True)
    run(p.parse_args().result)
